const $=s=>document.querySelector(s);const escapeHTML=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const clone=x=>JSON.parse(JSON.stringify(x));let template=localStorage.getItem('ruangcv-template')||'umum';if(!['umum','ats','teknik','komunikasi','seo','pribadi','minimalis','pendidikan','hukum','atskom'].includes(template))template='umum';
const storageKey=t=>t==='umum'?'ruangcv-data':t==='ats'?'ruangcv-ats-data':t==='teknik'?'ruangcv-teknik-data':t==='komunikasi'?'ruangcv-komunikasi-data':t==='seo'?'ruangcv-seo-data':t==='pribadi'?'ruangcv-pribadi-data':t==='minimalis'?'ruangcv-minimalis-data':t==='pendidikan'?'ruangcv-pendidikan-data':t==='hukum'?'ruangcv-hukum-data':'ruangcv-atskom-data';const initial=t=>t==='umum'?defaults:t==='ats'?atsDefaults:t==='teknik'?teknikDefaults:t==='komunikasi'?komunikasiDefaults:t==='seo'?seoDefaults:t==='pribadi'?pribadiDefaults:t==='minimalis'?minimalisDefaults:t==='pendidikan'?pendidikanDefaults:t==='hukum'?hukumDefaults:atskomDefaults;
function load(t){try{return JSON.parse(localStorage.getItem(storageKey(t)))||clone(initial(t))}catch{return clone(initial(t))}}let state=load(template);
function save(){try{localStorage.setItem(storageKey(template),JSON.stringify(state))}catch(e){console.warn('Tidak dapat menyimpan data:',e)}}function lines(text){return (text||'').split('\n').map(x=>x.trim()).filter(Boolean)}
function renderFields(){document.querySelectorAll('[data-field]').forEach(el=>el.value=state[el.dataset.field]||'');for(const type of (template==='teknik'?['education','experience','organizations','activities']:template==='hukum'?['education','experience','related']:['education','experience'])){let root=$('#'+type+'Fields');root.innerHTML=state[type].map((item,i)=>`<div class="repeat-card"><div class="repeat-header"><span>${type==='education'?'PENDIDIKAN':'PENGALAMAN'} ${String(i+1).padStart(2,'0')}</span><button class="remove" data-remove="${type}" data-index="${i}">Hapus ×</button></div><div class="form-grid"><label class="full">${type==='education'?((template==='komunikasi'||template==='seo'||template==='pribadi'||template==='minimalis'||template==='pendidikan'||template==='hukum'||template==='atskom')?'Nama sekolah / universitas':template!=='umum'?'Jurusan / pendidikan':'Nama sekolah / universitas'):((template==='minimalis'||template==='pendidikan')?'Jabatan / kegiatan':'Perusahaan / kegiatan')}<input data-type="${type}" data-index="${i}" data-key="title" value="${escapeHTML(item.title)}"></label><label class="full" style="${template==='pribadi'||((template==='minimalis'||template==='pendidikan')&&type==='experience')?'display:none':''}">${template!=='umum'?(type==='education'?((template==='komunikasi'||template==='seo'||template==='minimalis'||template==='pendidikan'||template==='hukum'||template==='atskom')?'Jurusan / program':'Sekolah / universitas'):'Jabatan / instansi'):(type==='education'?'Tahun & jurusan':'Jabatan / periode')}<textarea data-type="${type}" data-index="${i}" data-key="period" rows="2">${escapeHTML(item.period)}</textarea></label>${template!=='umum'?`<label class="full">Periode<input data-type="${type}" data-index="${i}" data-key="date" value="${escapeHTML(item.date)}" placeholder="Contoh: 2019 – 2022"></label>`:''}${template==='hukum'?`<label class="full">Lokasi<input data-type="${type}" data-index="${i}" data-key="location" value="${escapeHTML(item.location)}" placeholder="Kota, negara"></label>`:''}<label class="full" style="${template==='pribadi'||template==='minimalis'||(template==='pendidikan'&&type==='education')?'display:none':''}">Keterangan<textarea data-type="${type}" data-index="${i}" data-key="details" rows="3" placeholder="Satu poin per baris">${escapeHTML(item.details)}</textarea></label></div></div>`).join('')||'<p class="input-hint">Belum ada data. Klik + Tambah untuk mengisi.</p>'}if(template==='komunikasi'||template==='atskom')$('#skillgroupsFields').innerHTML=(state.skillgroups||[]).map((item,i)=>`<div class="repeat-card"><div class="repeat-header"><span>KATEGORI KEMAMPUAN ${String(i+1).padStart(2,'0')}</span><button class="remove" data-remove="skillgroups" data-index="${i}">Hapus ×</button></div><div class="form-grid"><label class="full">Nama kategori<input data-type="skillgroups" data-index="${i}" data-key="title" value="${escapeHTML(item.title)}"></label><label class="full">Keterangan<textarea data-type="skillgroups" data-index="${i}" data-key="details" rows="3">${escapeHTML(item.details)}</textarea></label></div></div>`).join('')||'<p class="input-hint">Belum ada data. Klik + Tambah untuk mengisi.</p>'}
function renderPreview(){for(const key of ['name','role','about','phone','email','website','address'])$('#p-'+key).textContent=state[key]||'';$('#cvPhoto').style.backgroundImage=`url("${state.photo}")`;$('#photoThumb').style.backgroundImage=`url("${state.photo}")`;$('#p-languages').innerHTML=lines(state.languages).map(x=>`<div class="language">${escapeHTML(x)}<div class="bar"></div></div>`).join('');$('#p-skills').innerHTML=lines(state.skills).map(x=>`<div class="skill">${escapeHTML(x)}</div>`).join('');for(const type of ['education','experience'])$('#p-'+type).innerHTML=state[type].map(x=>`<div class="cv-entry"><strong>${escapeHTML(x.title)}</strong><div class="sub">${escapeHTML(x.period)}</div>${lines(x.details).length?'<ul>'+lines(x.details).map(v=>'<li>'+escapeHTML(v)+'</li>').join('')+'</ul>':''}</div>`).join('');for(const key of ['name','role','about','phone','email','address'])$('#ats-'+key).textContent=state[key]||'';$('#atsPhoto').style.backgroundImage=`url("${state.photo}")`;for(const type of ['education','experience'])$('#ats-'+type).innerHTML=state[type].map(x=>`<div class="ats-item"><div class="ats-item-header"><strong>${escapeHTML(x.title)}</strong><span>${escapeHTML(x.date)}</span></div><div>${escapeHTML(x.period)}</div>${lines(x.details).length?'<ul>'+lines(x.details).map(v=>'<li>'+escapeHTML(v)+'</li>').join('')+'</ul>':''}</div>`).join('');for(const type of ['skills','certificates'])$('#ats-'+type).innerHTML=lines(state[type]).map(v=>'<li>'+escapeHTML(v)+'</li>').join('');renderTeknik();renderKomunikasi();renderSeo();renderPribadi();renderMinimalis();renderPendidikan();renderHukum();renderAtsKom();applyColors()}
