function updateTemplate(){const ats=template==='ats',tek=template==='teknik',com=template==='komunikasi',seo=template==='seo',per=template==='pribadi',min=template==='minimalis',pen=template==='pendidikan',law=template==='hukum',ak=template==='atskom';$('#cv').style.display=template==='umum'?'block':'none';$('#cvAts').style.display=ats?'block':'none';$('#cvTeknik').style.display=tek?'flex':'none';$('#cvKomunikasi').style.display=com?'block':'none';$('#cvSeo').style.display=seo?'flex':'none';$('#cvPribadi').style.display=per?'block':'none';$('#cvMinimalis').style.display=min?'block':'none';$('#cvPendidikan').style.display=pen?'block':'none';$('#cvAtsHukum').style.display=law?'block':'none';$('#cvAtsKom').style.display=ak?'block':'none';$('#photoRow').style.display=law||ak?'none':'flex';$('#websiteField').style.display=ats||seo||per?'none':'flex';$('#websiteFieldLabel').textContent=pen?'Instagram':law||ak?'LinkedIn':'Website / LinkedIn';$('#portfolioFieldLabel').textContent=law?'Website':'Portofolio';$('#aboutField').style.display=per?'none':'flex';$('#experienceBlock').style.display=per?'none':'block';$('#skillsBlock').style.display=per?'none':'block';$('#skillsHeading').textContent=min||pen||law?'Keahlian':ak?'Kemampuan & pelatihan':'Keahlian & bahasa';$('#pribadiExtra').style.display=per||min||pen?'block':'none';$('#pribadiExtraHeading').textContent=min||pen?'Kesukaan':'Hobi & organisasi';$('#organizationListField').style.display=min||pen?'none':'flex';$('#languagesField').style.display=ats||com||seo||min||pen||law||ak?'none':'flex';$('#skillsField').style.display=com||ak?'none':'flex';$('#addressField').style.display=com||min||ak?'none':'flex';$('#roleField').style.display=com||min||law||ak?'none':'flex';$('#portfolioField').style.display=com||law||ak?'flex':'none';$('#relatedExtra').style.display=law?'block':'none';$('#awardsField').style.display=law?'flex':'none';$('#skillGroupsExtra').style.display=com||ak?'block':'none';$('#certificatesField').style.display=ats||tek||law?'flex':'none';$('#personalExtra').style.display=tek||per?'block':'none';$('#activitiesExtra').style.display=tek?'block':'none';for(const id of ['softwareField','referencesField'])$('#'+id).style.display=tek?'flex':'none';const name=ak?'CV ATS Komunikasi':law?'CV ATS Hukum':pen?'CV Pendidikan':min?'CV Minimalis':per?'CV Pribadi Emas':seo?'CV SEO Specialist':com?'CV Komunikasi':tek?'CV Teknik Mesin':ats?'CV ATS':'CV Umum';$('#activeTemplateName').textContent=name;$('#topTemplate').textContent=name;$('#activeTemplateImage').src=ak?'assets/cv-ats-komunikasi.webp':law?'assets/cv-ats-hukum.jpeg':pen?'assets/cv-pendidikan.jpeg':min?'assets/cv-minimalis.jpg':per?'assets/cv-pribadi.webp':seo?'assets/cv-seo.jpg':com?'assets/cv-komunikasi.jpeg':tek?'assets/cv-teknik.jpeg':ats?'assets/cv-ats.jpeg':'assets/cv-umum.jpeg';$('#activeTemplateDesc').textContent=ak?'Tanpa foto, satu kolom':law?'Tanpa foto, teks sederhana':pen?'Profesional bidang pendidikan':min?'Hitam putih dua kolom':per?'Hitam dan emas':seo?'Desain profesional dua warna':com?'Desain biru profesional':tek?'Lulusan S1 Teknik Mesin':ats?'Sederhana & profesional':'Profesional & serbaguna';for(const key of ['umum','ats','teknik','komunikasi','seo','pribadi','minimalis','pendidikan','hukum','atskom'])$('#selected-'+key).style.display=template===key?'block':'none';renderFields();renderPreview();syncColorControls()}
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.field){state[t.dataset.field]=t.value;save();renderPreview()}else if(t.dataset.type){state[t.dataset.type][Number(t.dataset.index)][t.dataset.key]=t.value;save();renderPreview()}});
document.addEventListener('click',e=>{const add=e.target.closest('[data-add]');if(add){state[add.dataset.add].push({title:'',period:'',date:'',details:''});save();renderFields();renderPreview()}const remove=e.target.closest('[data-remove]');if(remove){state[remove.dataset.remove].splice(Number(remove.dataset.index),1);save();renderFields();renderPreview()}const choice=e.target.closest('[data-template]');if(choice){save();template=choice.dataset.template;localStorage.setItem('ruangcv-template',template);state=load(template);updateTemplate();closeModal()}});
$('#photoInput').addEventListener('change',e=>{let file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024){alert('Ukuran foto maksimal 5 MB.');e.target.value='';return}const r=new FileReader();r.onload=()=>{const image=new Image();image.onload=()=>{const canvas=document.createElement('canvas');const ats=template==='ats',tek=template==='teknik',seo=template==='seo';canvas.width=400;canvas.height=ats?585:tek?461:seo?557:400;const ctx=canvas.getContext('2d');const ratio=canvas.width/canvas.height;let w=image.width,h=image.height;if(w/h>ratio)w=h*ratio;else h=w/ratio;ctx.drawImage(image,(image.width-w)/2,(image.height-h)/2,w,h,0,0,canvas.width,canvas.height);state.photo=canvas.toDataURL('image/jpeg',.82);save();renderPreview()};image.src=r.result};r.readAsDataURL(file);e.target.value=''});
