 for(const item of state.education||[]){check(10);font(15,'bold');doc.text(`${(item.title||'').toUpperCase()} (${item.date||''})`,left,y,{maxWidth:full});y+=lead;paragraph(item.period);for(const detail of lines(item.details)){y+=1;let colon=detail.indexOf(':');font(14);let rows=doc.splitTextToSize(detail,full);for(let i=0;i<rows.length;i++){check(lead);if(i===0&&colon>=0&&rows[0].startsWith(detail.slice(0,colon+1))){let label=detail.slice(0,colon+1);font(15,'bold');doc.text(label,left,y);let x=left+doc.getTextWidth(label);font(14);doc.text(rows[0].slice(label.length),x,y)}else{font(14);doc.text(rows[i],left,y)}y+=lead}}y+=1.5}
 y+=1;heading('PENGALAMAN');for(const [i,item] of (state.experience||[]).entries()){check(10);font(15,'bold');doc.text(item.title||'',left,y,{maxWidth:full});y+=lead;let title=item.period||'',suffix=item.date?' ('+item.date+')':'';font(14,i===0?'italic':'normal');let width=doc.getTextWidth(title);font(14);let suffixWidth=doc.getTextWidth(suffix);if(width+suffixWidth<=full){check(lead);font(14,i===0?'italic':'normal');doc.text(title,left,y);font(14);doc.text(suffix,left+width,y);y+=lead}else{font(14);for(const row of doc.splitTextToSize(title+suffix,full)){check(lead);doc.text(row,left,y);y+=lead}}y+=.8;bullets(item.details);y+=2}
 heading('KEMAMPUAN & PELATIHAN');for(const [i,item] of (state.skillgroups||[]).entries()){check(lead*2);font(15,'bold');doc.text(item.title||'',left,y,{maxWidth:full});y+=lead;paragraph(item.details,i<2?'italic':'normal');y+=1.8}
