async function savePdf(){const buttons=[$('#downloadBtn'),$('#mobileDownload')];buttons.forEach(b=>b.disabled=true);try{const {jsPDF}=window.jspdf;const doc=new jsPDF({orientation:'portrait',unit:'mm',format:'a4'});if(template==='ats'){await createAtsPdf(doc)}else if(template==='hukum'){createLawPdf(doc)}else if(template==='atskom'){createAtsKomPdf(doc)}else{const copy=$(template==='pendidikan'?'#cvPendidikan':template==='minimalis'?'#cvMinimalis':template==='pribadi'?'#cvPribadi':template==='seo'?'#cvSeo':template==='komunikasi'?'#cvKomunikasi':template==='teknik'?'#cvTeknik':'#cv').cloneNode(true);copy.style.cssText='display:'+((template==='teknik'||template==='seo')?'flex':'block')+';position:fixed;left:0;top:0;z-index:-10000;transform:none';copy.style.setProperty('--cv-primary',palette().primary);copy.style.setProperty('--cv-accent',palette().accent);document.body.appendChild(copy);try{const canvas=await html2canvas(copy,{scale:2,backgroundColor:'#ffffff',useCORS:true});doc.addImage(canvas.toDataURL('image/jpeg',.96),'JPEG',0,0,210,297)}finally{copy.remove()}}const filename=(state.name||'CV').trim().replace(/[\\/:*?"<>|]/g,'').replace(/\s+/g,' ')||'CV';doc.save(filename+'.pdf')}catch(err){console.error(err);alert('PDF belum berhasil disimpan. Silakan coba lagi.')}finally{buttons.forEach(b=>b.disabled=false)}}$('#downloadBtn').onclick=savePdf;$('#mobileDownload').onclick=savePdf;
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));$('.workspace').classList.toggle('preview-active',b.dataset.view==='preview');scalePreview()});$('#templateInfo').onclick=()=>{$('#templateModal').classList.add('open');$('#templateModal').setAttribute('aria-hidden','false')};function closeModal(){$('#templateModal').classList.remove('open');$('#templateModal').setAttribute('aria-hidden','true')}document.querySelectorAll('.modal-close,.modal-backdrop').forEach(b=>b.onclick=closeModal);
// Two-color HSV picker: the square controls saturation/value and the slider controls hue.
let activeColor='primary',hsv={h:0,s:0,v:0};
function palette(){return {...palettes[template],...(state.palette||{})}}
function hexRGB(hex){let v=hex.replace('#','');return [parseInt(v.slice(0,2),16),parseInt(v.slice(2,4),16),parseInt(v.slice(4,6),16)]}
function hexToHsv(hex){let [r,g,b]=hexRGB(hex).map(x=>x/255),max=Math.max(r,g,b),min=Math.min(r,g,b),d=max-min,h=0;if(d){if(max===r)h=((g-b)/d)%6;else if(max===g)h=(b-r)/d+2;else h=(r-g)/d+4;h=(h*60+360)%360}return {h,s:max?d/max:0,v:max}}
function hsvToHex(h,s,v){let c=v*s,x=c*(1-Math.abs((h/60)%2-1)),m=v-c;let rgb=h<60?[c,x,0]:h<120?[x,c,0]:h<180?[0,c,x]:h<240?[0,x,c]:h<300?[x,0,c]:[c,0,x];return '#'+rgb.map(a=>Math.round((a+m)*255).toString(16).padStart(2,'0')).join('')}
function applyColors(){let p=palette();for(const id of ['cv','cvAts','cvTeknik','cvKomunikasi','cvSeo','cvPribadi','cvMinimalis','cvPendidikan','cvAtsHukum','cvAtsKom']){let el=$('#'+id);el.style.setProperty('--cv-primary',p.primary);el.style.setProperty('--cv-accent',p.accent)}document.querySelectorAll('.personal-primary').forEach(el=>el.style.fill=p.primary);document.querySelectorAll('.personal-accent').forEach(el=>el.style.fill=p.accent);const chips=document.querySelectorAll('.swatches i');if(chips[0])chips[0].style.background=p.primary;if(chips[1])chips[1].style.background=p.accent}
function updateColorUI(){const color=hsvToHex(hsv.h,hsv.s,hsv.v);$('#colorSquare').style.background=`linear-gradient(to top,#000,transparent),linear-gradient(to right,#fff,transparent),hsl(${hsv.h},100%,50%)`;$('#colorMarker').style.left=(hsv.s*100)+'%';$('#colorMarker').style.top=((1-hsv.v)*100)+'%';$('#colorSquare').setAttribute('aria-valuetext',color);$('#hueSlider').value=Math.round(hsv.h);$('#hexInput').value=color.slice(1).toUpperCase();document.querySelectorAll('[data-color-slot]').forEach(b=>{b.classList.toggle('active',b.dataset.colorSlot===activeColor);b.querySelector('i').style.background=palette()[b.dataset.colorSlot]})}
function syncColorControls(){hsv=hexToHsv(palette()[activeColor]);updateColorUI();applyColors()}
function setColor(){state.palette={...palette(),[activeColor]:hsvToHex(hsv.h,hsv.s,hsv.v)};save();applyColors();updateColorUI()}
document.querySelectorAll('[data-color-slot]').forEach(b=>b.addEventListener('click',()=>{activeColor=b.dataset.colorSlot;syncColorControls()}));$('#hueSlider').addEventListener('input',e=>{hsv.h=Number(e.target.value)%360;setColor()});const square=$('#colorSquare');function squarePosition(e){const r=square.getBoundingClientRect();hsv.s=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width));hsv.v=1-Math.max(0,Math.min(1,(e.clientY-r.top)/r.height));setColor()}square.addEventListener('pointerdown',e=>{square.setPointerCapture(e.pointerId);squarePosition(e)});square.addEventListener('pointermove',e=>{if(square.hasPointerCapture(e.pointerId))squarePosition(e)});square.addEventListener('keydown',e=>{let step=e.shiftKey?.1:.01;if(e.key==='ArrowLeft')hsv.s=Math.max(0,hsv.s-step);else if(e.key==='ArrowRight')hsv.s=Math.min(1,hsv.s+step);else if(e.key==='ArrowUp')hsv.v=Math.min(1,hsv.v+step);else if(e.key==='ArrowDown')hsv.v=Math.max(0,hsv.v-step);else return;e.preventDefault();setColor()});$('#hexInput').addEventListener('change',e=>{let v=e.target.value.trim().replace(/^#/,'');if(/^[0-9a-f]{6}$/i.test(v)){hsv=hexToHsv('#'+v);setColor()}else{alert('Masukkan kode warna 6 digit, misalnya 1C2C45.');updateColorUI()}});$('#resetColors').onclick=()=>{state.palette={...palettes[template]};save();syncColorControls()};
function scalePreview(){const canvas=$('.canvas');if(!canvas.clientWidth)return;let scale=Math.min(1,(canvas.clientWidth-24)/465);$('#cvScale').style.transform=`scale(${scale})`;$('#cvScale').style.transformOrigin='top left';$('.canvas-inner').style.width=(465*scale)+'px';$('.canvas-inner').style.height=(659*scale)+'px'}window.addEventListener('resize',scalePreview);updateTemplate();scalePreview();
